      "week": 3,
      "title": "Early Humanity and the Agricultural Revolution",
      "unit": "Unit 1 · The Historian’s World",
      "period": "Prehistory to c. 3000 BCE",
      "regions": "Africa, Eurasia, Oceania, Americas",
      "essentialQuestion": "Did agriculture improve human life, or did it exchange some freedoms for new forms of security and inequality?",
      "vocabulary": {
        "Paleolithic": "The period when humans generally lived by hunting, gathering, and fishing.",
        "Neolithic": "The later Stone Age associated in many regions with agriculture and settled communities.",
        "domestication": "The long-term process of selecting and managing plants or animals for human use.",
        "surplus": "Production beyond immediate consumption needs.",
        "specialization": "The concentration of labor on particular tasks or skills.",
        "archaeology": "The study of past societies through material remains and their contexts."
      },
      "keyUnderstandings": [
        "Homo sapiens originated in Africa and migrated over many generations into diverse environments.",
        "Agriculture developed independently in several regions rather than spreading from a single universal center.",
        "Food surplus supported larger settlements and specialization but also contributed to hierarchy, disease exposure, and conflict."
      ],
      "readingSections": [
        {
          "heading": "Setting the Stage",
          "text": "For most of human history, people lived in mobile or semi-mobile communities. They used detailed environmental knowledge to gather plants, hunt, fish, manage fire, and move with seasons. Archaeological evidence shows innovation in tools, art, exchange, clothing, and shelter long before farming."
        },
        {
          "heading": "People, Power, and Systems",
          "text": "Between roughly 12,000 and 4,000 BCE, communities in several regions increasingly domesticated plants and animals. This process was gradual. Some groups combined cultivation with hunting and gathering for centuries. Farming could support larger populations, yet it also required sustained labor, storage, land claims, and defense."
        },
        {
          "heading": "Reading the Evidence",
          "text": "Archaeologists examine seeds, animal bones, pollen, grinding stones, settlement layers, and human remains. Evidence may reveal changing diets, workloads, disease, and social differences. Because evidence survives unevenly, researchers compare sites and remain cautious about assuming that all communities followed the same path."
        },
        {
          "heading": "Why It Matters",
          "text": "The agricultural transition changed relationships among people, land, and authority. Surplus could support craft specialists and leaders, but access to stored food and fertile land could become unequal. The transition therefore created both opportunities and problems that later societies inherited."
        }
      ],
