      "week": 23,
      "title": "Atlantic Slavery, Colonialism, and Resistance",
      "unit": "Unit 5 · The Early Modern World",
      "period": "c. 1450–1888 CE",
      "regions": "Africa, Atlantic, Americas, Europe",
      "essentialQuestion": "How did racial slavery become embedded in Atlantic economies, and how did enslaved people resist?",
      "vocabulary": {
        "chattel slavery": "A system treating enslaved people as legally owned property, often for life and by descent.",
        "Middle Passage": "The forced Atlantic voyage carrying enslaved Africans to the Americas.",
        "plantation": "A large agricultural enterprise relying on controlled labor to produce cash crops.",
        "racialization": "The process of assigning social meaning and hierarchy to perceived physical differences.",
        "abolition": "The movement and process of ending slavery.",
        "maroon community": "A community established by people who escaped slavery."
      },
      "keyUnderstandings": [
        "African societies had varied relationships to slavery, but Atlantic demand expanded warfare, capture, and human trafficking.",
        "European colonial law increasingly made slavery racial, hereditary, and permanent.",
        "Enslaved people resisted through survival, family, culture, work slowdowns, escape, revolt, legal petitions, and abolitionist organizing."
      ],
      "readingSections": [
        {
          "heading": "Setting the Stage",
          "text": "The Atlantic slave trade forcibly transported millions of Africans over more than three centuries. European traders, African political actors, merchants, and American plantation owners participated in a changing system, but European colonial demand and shipping networks drove its enormous expansion."
        },
        {
          "heading": "People, Power, and Systems",
          "text": "Plantation economies produced sugar, tobacco, rice, coffee, and cotton for distant markets. Colonial laws defined people as property and made status inheritable through the mother in many jurisdictions. Racial ideologies developed to justify exploitation and unequal rights."
        },
        {
          "heading": "Reading the Evidence",
          "text": "Ship records quantify voyages but reduce people to categories. Narratives, court petitions, advertisements, songs, archaeology, and family histories restore individual experience while showing source limits. Resistance occurred every day as well as in famous rebellions."
        },
        {
          "heading": "Why It Matters",
          "text": "Atlantic slavery shaped wealth, law, race, migration, foodways, music, religion, and political debate across several continents. Its legacies did not end with legal abolition."
        }
      ],
