          "heading": "People, Power, and Systems",
          "text": "Karl Marx and Friedrich Engels argued that capitalist ownership produced class conflict and exploitation. Other socialists preferred democratic reform, cooperatives, or municipal ownership. Labor unions fought for shorter hours, safer workplaces, wages, and political rights."
